data/grammaire/objets.yaml:
# Objets et compléments confirmés par le locuteur, pour varier les phrases.
# `objets` : ce qui se place après di / na (phrases avec objet).
# `complements` : lieu ou moment, à la fin de la phrase ; `temps` limite les temps compatibles.
# Chaque entrée porte sa traduction française (article compris).

# `verbes` limite l'objet aux verbes qui l'acceptent (on ne mange pas du lait).
objets:
  - {snk: maro, fr: du riz, verbes: [yigeyer, wori], source: "corp1 #28"}
  - {snk: "maro ke", fr: le riz, verbes: [yigeyer, wori], source: "serie_03"}
  - {snk: xati, fr: du lait, verbes: [mini, wori], source: "2026-09-17"}
  - {snk: "xati ke", fr: le lait, verbes: [mini, wori], source: "2026-09-17"}
  - {snk: lemine, fr: un enfant, verbes: [wori], source: "serie_02 #26"}
  - {snk: "lemine ke", fr: l'enfant, verbes: [wori], source: "serie_03"}
  - {snk: lettra, fr: une lettre, verbes: [safa, wori], source: "serie_03 #16"}
  - {snk: "lettra ke", fr: la lettre, verbes: [safa, wori], source: "serie_03 #16"}

complements:
  - {snk: saxa, fr: au marché, source: "corp1 #27"}
  - {snk: lenki, fr: aujourd'hui, source: "serie_02 #19",
     temps: [past, past_object, demande, demande_objet, en_cours]}
  - {snk: daru, fr: hier, source: "corp1 #29", temps: [past, past_object]}
  - {snk: kumbene, fr: demain, source: "corp1 #30", temps: [future]}
  - {snk: "koota su", fr: tous les jours, source: "2026-09-20", temps: [en_cours, en_cours_objet, en_cours_fayi, en_cours_objet_fayi]}
  - {snk: "waxati su", fr: à tout moment, source: "2026-09-20",
     temps: [en_cours, en_cours_objet, en_cours_fayi, en_cours_objet_fayi]}

data/references/mots.yaml:
# Mots donnés par le locuteur (hors verbes). Pas encore lus par le moteur :
# ils serviront à construire les phrases avec objet et compléments.
# Orthographe du projet (x, u, e, g). « ? » = à confirmer.

noms:
  - {snk: lemine, fr: enfant, source: "serie_02 #26, serie_03"}
  - {snk: maro, fr: riz, source: "corp1 #28, confirmé 2026-09-17"}
  - {snk: xati, fr: lait, source: "2026-09-17"}
  - {snk: saxa, fr: marché, source: "corp1 #27"}
  - {snk: lettra, fr: lettre, source: "serie_03 #16", note: "variante donnée : fare"}
  - {snk: fare, fr: "lettre ?", source: "serie_03 #16", note: "à confirmer ; fare = âne chez Creissels"}
  - {snk: soninke, fr: soninké (la langue), source: "serie_02 #18"}

temps:
  - {snk: lenki, fr: aujourd'hui, source: "serie_02 #19"}
  - {snk: daru, fr: hier, source: "corp1 #29"}
  - {snk: kumbene, fr: demain, source: "corp1 #30"}

grammaire:
  - {snk: ke, fr: "le/la (met l'accent sur le nom)", source: "serie_03, précisé 2026-09-17",
     note: "placé APRÈS le nom (lemine ke, maro ke) ; facultatif, mais habituel dans ce dialecte.
            Sert surtout à signaler qu'il s'agit de celui dont on parle déjà (l'enfant en question)."}
  - {snk: di, fr: "marqueur d'objet (passé)", source: "corp1 #28, serie_03"}
  - {snk: maxa, fr: "négation (passé)", source: "corp1 #20"}
  - {snk: mi, fr: "négation (passé), forme courte de maxa", source: "serie_03 #19-21",
     note: "« mi est un diminutif de maxa, très souvent utilisé »"}
  - {snk: "n'ti rini / n'taxa rini", fr: "négation (futur)", source: "serie_03, confirmé 2026-09-17",
     note: "maxa pour le passé, n'ti/n'taxa pour le futur"}
  - {snk: watia, fr: "insiste sur le moment", source: "corp1 #3"}
  - {snk: ya ba, fr: "marque la question (oui/non)", source: "corp1 #24"}
  - {snk: mina, fr: où, source: "corp1 #25"}
  - {snk: "mane ni … gi", fr: "pourquoi", source: "corp1 #22"}
  - {snk: kan dimma, fr: quand, source: "corp1 #26"}

adverbes:
  - {snk: siri, fr: "mal (douleur, non tangible)", source: "serie_03 #35"}
  - {snk: gobo, fr: "beaucoup (de personnes)", source: "confirmé 2026-09-20",
     exemple: "lemina n'gobo = beaucoup d'enfants"}
  - {snk: gebe, fr: "beaucoup (de choses)", source: "confirmé 2026-09-20",
     exemple: "yite gebe = beaucoup d'arbres", note: "écrit gabo dans texte_journee"}

# --- texte_journee (2026-09-17) : compris à ~96 %, à vérifier un par un ---
texte_journee:
