    - {snk: ga, fr: "introduit la subordonnée", exemple: "o ga dagana noqu be"}
    - {snk: "kati … n'ga", fr: "avant de", exemple: "kati n'ga baka ka ke noxo"}
    - {snk: "-ni / -yi / -nu", fr: "pluriel", exemple: "yoku-ni, kine-yi, xana-nu"}
    - {snk: noxo, fr: "dans", exemple: "ka ke noxo"}
    - {snk: "m'falle", fr: après, exemple: "locolou m'falle"}
    - {snk: "m'fallaqe", fr: devant, exemple: "o ka m'fallaqe"}
    - {snk: "do me", fr: ensemble}
    - {snk: ma, fr: "jusqu'à", exemple: "o na tere ma saxa"}
    - {snk: bawoni, fr: parce que}
    - {snk: kempale, fr: ensuite}
    - {snk: su, fr: "chaque / tout", exemple: "suxuba su, sere su"}
    - {snk: be, fr: "qui / que / où"}
    - {snk: xadi, fr: encore}
    - {snk: "i / ni / o", fr: "son / mon / notre (avant le nom)"}
    - {snk: "-na", fr: "forme un nom de métier", exemple: "gaaga-na = le vendeur"}
  noms:
    - {snk: suxuba, fr: matin}
    - {snk: "suxuba m'po", fr: petit-déjeuner}
    - {snk: kiye, fr: soleil}
    - {snk: dji, fr: eau}
    - {snk: ka, fr: maison}
    - {snk: xoxone, fr: frère}
    - {snk: yiramu, fr: habits}
    - {snk: yoku-ni, fr: choses}
    - {snk: taxalema, fr: voisin}
    - {snk: dionko-ni, fr: prix}
    - {snk: wetieti, fr: monnaie}
    - {snk: xaju, fr: besoin}
    - {snk: yerexate, fr: repas}
    - {snk: kine-yi, fr: aliments}
    - {snk: bara, fr: cour}
    - {snk: dimma, fr: moment}
    - {snk: xara moxo, fr: professeur}
    - {snk: xana-nu, fr: amis}
    - {snk: lele, fr: soir}
    - {snk: sere, fr: personne}
    - {snk: mburu, fr: pain}
    - {snk: "yite-remu", fr: fruits}
    - {snk: teh, fr: "huile", note: "corrigé 2026-09-25 : teh = huile, le thé est hataye"}

# --- Précisions du locuteur (serie_04_termes, 2026-09-17) ---
serie_04:
  - {snk: beteye, fr: midi}
  - {snk: "xara-kompe", fr: école, note: "littéralement la maison où l'on apprend ; lokolou est l'emprunt courant"}
  - {snk: lemane, fr: un peu, exemple: "o na fo lemane sefe = nous parlons un peu"}
  - {snk: xoto, fr: difficile}
  - {snk: siri, fr: "bien (bien fait)"}
  - {snk: sarano, fr: "les parents (père et mère)"}
  - {snk: bara, fr: "cour, espace"}
  - {snk: "-su", fr: "chaque / tout", exemple: "suxuba-su, lele-su, sere-su"}
  - {snk: "-ni", fr: "pluriel", exemple: "maro-ni = les riz"}
  - {snk: "m'fallaqe", fr: derrière, note: "corrigé : derrière, et non devant ; proche de m'falle (après)"}
  - {snk: "do me", fr: "ensemble", note: "o na tere do me, o na yige do me, o na xara do me"}
  - {snk: "o ya / oku ya", fr: "à nous"}
  - {snk: possessifs, fr: "n, an, a, o, xa, i + nom", exemple: "a ka = sa maison, i yiramu = leurs vêtements"}
  - {snk: na, fr: "présent (on explique ce qu'on fait)", exemple: "nke na wutu = je prends ; nke di wutu = je l'ai déjà pris"}
  - {snk: di, fr: "accompli (action déjà faite)", note: "sert aussi devant l'objet"}
  - {snk: "ŋ'", fr: "particule devant w ?", note: "serie_04 : ŋ'wori (voir) ; mais corp1 : n'wuru (courir). À trancher."}

# --- texte_marche (2026-09-17) : compris d'après le texte, à confirmer ---
texte_marche:
  questions:
    - {snk: minna, fr: où, exemple: "anke dagana minna ?"}
    - {snk: "mane-ni", fr: pourquoi, exemple: "mane-ni anke n'ga dagana saxa ?"}
    - {snk: mane, fr: quoi, exemple: "an di mane xobo daru ?"}
    - {snk: ko, fr: qui, exemple: "anke n'do ko dagana do me ?"}
    - {snk: "kan dimma", fr: quand}
    - {snk: "mani-me", fr: combien, exemple: "mani-me ni maro ?"}
    - {snk: ba, fr: "marque la question oui/non (en fin de phrase)"}
    - {snk: ayi, fr: non}
  copule_et_avoir:
    - {snk: yi, fr: "être (quelque part)", exemple: "a yi ka ke = elle est à la maison"}
    - {snk: "n'ti", fr: "ne pas être", exemple: "ake n'ti ka ke = elle n'est pas à la maison"}
    - {snk: ni, fr: "c'est (copule)", exemple: "nke faba ka n'ya ni = c'est la maison de mon père"}
    - {snk: "ya", fr: "met en relief (focus)", exemple: "(maro ado te-ni)-ni ya xobono",
       note: "confirmé : ce que je lisais « n'ya » est le -ni du nom suivi de ya"}
    - {snk: maxa, fr: "chez, avec (possession)", exemple: "xalisi n'ti maxa = je n'ai pas d'argent"}
    - {snk: fayi, fr: "être (là), être en train de, regarder", exemple: "n waxi-ni ku fayi locolou",
       note: "confirmé : c'est le même mot dans les trois emplois"}
  pluriel_et_determinants:
    - {snk: ku, fr: "les (déterminant pluriel, pendant de ke)", exemple: "leminu ku, n waxi-ni ku"}
    - {snk: "-ni / -mu", fr: "pluriel du nom", exemple: "waxi-ni, taxa-lemu"}
  nombres:
    - {snk: filli, fr: deux}
    - {snk: siki, fr: trois}
  noms:
    - {snk: faba, fr: père}
    - {snk: waxi, fr: "frère (waxi-ni = frères)", note: "xoxone = petit frère"}
    - {snk: "guida xaxaru", fr: sœur, note: "corrigé : xaxaru, et non naxaru"}
    - {snk: remme, fr: "enfant (remu = enfants)"}
    - {snk: gunne, fr: champ}
    - {snk: xalisi, fr: argent}
    - {snk: xase, fr: vieux}
    - {snk: yere, fr: ici}
    - {snk: ngebe, fr: beaucoup}
    - {snk: do, fr: avec}
  imperatif:
    - {snk: taxu, fr: "assieds-toi"}
    - {snk: yeli, fr: "viens"}
    - {snk: "maro ke yiga", fr: "mange le riz (objet + verbe)"}
    - {snk: "maxa daga", fr: "ne pars pas"}
    - {snk: "xa guiri / xa terinke / xa maxa mungo", fr: "levez-vous / écoutez / n'oubliez pas (xa = vous)"}
    - {snk: "a nia ti allah", fr: "s'il te plaît"}
    - {snk: "a wara", fr: "laisse-le"}
    - {snk: siri, fr: "pas beaucoup", exemple: "xa maxa yige siri = ne mangez pas beaucoup",
       note: "ailleurs : bien (bien fait)"}
  corrections:
    - "« nke fayi dagana saxa » était une erreur : la bonne forme est nke fayi rini daga."
    - "« An l'rini kan dimma » était une erreur : les pronoms diminutifs ne prennent pas la particule."

# --- texte_village (2026-09-17) : lecture de Claude, à confirmer ---
texte_village:
  constructions:
    - {snk: "yi + forme en -nu", fr: "état / action en cours dans le passé",
       exemple: "ma-ma yi taxunu = elle était assise ; nke ni terene = je marchais"}
    - {snk: "n'gana", fr: "si", exemple: "an n'gana daga watia = si tu pars maintenant"}
    - {snk: "n'ga / ga", fr: "quand", exemple: "kiye n'ga xenu = quand le soleil s'est couché"}
    - {snk: "ti … da", fr: "dire à", exemple: "a ti n'da = elle m'a dit"}
    - {snk: nanti, fr: "que (parole rapportée)", exemple: "n'ti a da nanti nke daga na ya"}
    - {snk: "dinan-ti", fr: "que (comparaison)", exemple: "a ka ke lamane ni ya dinan-ti o ka"}
    - {snk: xa, fr: mais}
    - {snk: yogo, fr: "un (indéfini)", exemple: "yigu-xoso yogo ri = un vieil homme est venu"}
    - {snk: "ya", fr: "à / chez (postposition)", exemple: "kini nke ya = donner à moi ; ma debe ke ya",
       note: "confirmé 2026-09-17"}
    - {snk: "ni ya", fr: "est (avec un adjectif)", exemple: "towoyinte ni ya = il est malade ; xore ni ya = elle est grande",
       note: "confirmé 2026-09-17"}
    - {snk: wure, fr: sous, exemple: "yite xore ŋ'wure = sous le grand arbre"}
    - {snk: moxo, fr: "comment", exemple: "a ma-ma moxo ? = comment va ta grand-mère ?"}
    - {snk: "yi / ti", fr: "est / n'est pas (auxiliaire)", exemple: "nke yi mula = je le veux ; nke ti mula = je ne veux pas",
       note: "confirmé. Explique sans doute yi rini (futur) et n'ti rini (futur négatif)"}
    - {snk: "n (objet)", fr: "me (avant le verbe)", exemple: "a di ŋ'wori = a di nke wori = elle m'a vu",
       note: "confirmé : les deux formes se disent ; ŋ' est le n assimilé"}
    - {snk: siri, fr: "renforce le mot (longtemps, vite, beaucoup)", note: "confirmé : le sens dépend du contexte"}
    - {snk: kaane, fr: "avant / plus tard", note: "confirmé : c'est le même mot"}
  noms:
    - {snk: "ma-ma", fr: grand-mère}
    - {snk: kissima, fr: grand-père}
    - {snk: kawu, fr: oncle}
    - {snk: debe, fr: village, note: "debe xoore = la ville (grand village)"}
    - {snk: kille, fr: route}
    - {snk: xibaru, fr: nouvelles}
    - {snk: wuro, fr: nuit}
    - {snk: goli, fr: travail}
    - {snk: "yigu-xoso", fr: vieil homme}
    - {snk: yite, fr: arbre}
  adjectifs:
    - {snk: gillo, fr: long}
    - {snk: xore, fr: grand}
    - {snk: lamane, fr: petit}
    - {snk: towoyinte, fr: malade}
    - {snk: diomu, fr: "bien, en bonne santé"}
    - {snk: "fene fene", fr: tôt}
  corrections_village:
    - "« A l'ri ? » était une erreur : la bonne forme est An l'ri (tu es venu)."

# --- 2026-09-20 ---
# « su » = chaque : il se place APRÈS le nom et s'écrit séparément (confirmé 2026-09-20)
chaque:
  - {snk: "koota su", fr: "chaque jour / tous les jours"}
  - {snk: "waxati su", fr: "chaque moment"}
  - {snk: "sere su", fr: "chaque personne"}
  - {snk: "dinguira su", fr: "chaque endroit"}
  - {snk: "suxuba su", fr: "chaque matin"}
  - {snk: "lele su", fr: "chaque soir"}
  - {snk: waxati, fr: moment}
  - {snk: dinguira, fr: endroit}
  - {snk: koota, fr: "jour ou heure ?", note: "à confirmer"}

# --- texte_travail (2026-09-20) : lecture de Claude, à confirmer ---
texte_travail:
  - {snk: "ni a ni / niani", fr: "il y a", exemple: "yite gabo ni a ni a noxo = il y a beaucoup d'arbres dedans"}
  - {snk: "ni ya", fr: "facilite la transition entre les mots", exemple: "nke goli ni ya koota su",
     note: "confirmé : « nke yi golini koota su » est également correct"}
  - {snk: "watia kundu", fr: "en ce moment"}
  - {snk: kati, fr: "à (destinataire) et avant", exemple: "kati nke waxi = à mon frère ; kati wuro ke nga roono = avant la nuit",
     note: "confirmé : c'est le même mot"}
  - {snk: xa, fr: "où ?", exemple: "an guida xa ?", note: "confirmé : équivaut à minna — « an guida ni minna » se dit aussi"}
  # « kotaxu » était une faute de frappe pour « kota su »
  - {snk: gune, fr: champ}
  - {snk: kompo, fr: chambre, note: "kompe ke = la chambre"}
  - {snk: fana, fr: "premier", exemple: "kompe fana ke = la première chambre"}
  - {snk: saxura, fr: lit}
  - {snk: kaye, fr: cahier}
  - {snk: gabo, fr: beaucoup, exemple: "yite gabo", note: "= gebe (pour des choses)"}
  - {snk: tie, fr: viande}
  - {snk: guida, fr: frère, note: "confirmé 2026-09-25 ; guida niaxare = sœur"}
  - {snk: "guida niaxare", fr: "grande sœur"}
  - {snk: "guida n'yigo", fr: "grand frère"}
  - {snk: "a do … me", fr: "être en train de", exemple: "guida niaxare a do yirame waqinde me = ma sœur est en train de laver les habits"}
  - {snk: yille, fr: rentrer}
  - {snk: waqinde, fr: "lavé", note: "wanqi ailleurs"}
  - {snk: deberi, fr: faire, exemple: "ake ni mane deberini watia ? = qu'est-ce qu'il fait maintenant ?"}

  - {snk: ke, fr: "le/la", note: "confirmé : se place avant ou après le nom — ke suxuba = suxuba ke"}

# --- Les noms (2026-09-20) : pluriel, possessifs, il y a, nombres ---
noms_systeme:
  pluriel:
    - {sg: "ka ke", pl: "kanu ku", fr: la maison / les maisons, note: "« ka ni ku » était une erreur"}
    - {sg: "lemine ke", pl: "leminu ku", fr: l'enfant / les enfants}
    - {sg: "yite ke", pl: "yitu ku", fr: l'arbre / les arbres}
    - {note: "confirmé : ke = déterminant singulier, ku = déterminant pluriel"}
    - {sg: mburu, pl: mburuni, fr: pain, exemple: "mburuni filli = deux pains"}
    - {sg: banana, pl: bananani, fr: banane, exemple: "bananani tami = dix bananes"}
    - {note: "nom en -e → finale -u (lemine → leminu) ; nom en -u ou -a → + -ni (mburu → mburuni)"}
  compte:
    - {snk: "lemina m'bane", fr: un enfant}
    - {snk: "leminu filli", fr: deux enfants}
    - {snk: "leminu sikki", fr: trois enfants}
    - {snk: "kanu tami", fr: dix maisons}
    - {snk: "lemina n'gobo", fr: beaucoup d'enfants}
    - {snk: "lemina lamanu", fr: peu d'enfants}
    - {note: "confirmé : avec « un » le nom reste au singulier (lemina m'bane) ; à partir de deux il est au pluriel (leminu filli)"}
  possessifs:
    - {snk: "n ka ke / an ka ke / a ka ke / o ka ke / xa ka ke / i ka ke",
       fr: "ma / ta / sa / notre / votre / leur maison", note: "corrigé 2026-09-20 : le « ke » est conservé"}
    - {snk: "n'paba ka", fr: la maison de mon père, note: "n + faba → n'paba : f devient p"}
    - {snk: "lemine ke kaye", fr: le cahier de l'enfant, note: "possesseur + possédé, sans mot de liaison"}
  il_y_a:
    - {snk: "lemine yi ka ke noxo", fr: il y a un enfant dans la maison}
    - {snk: "leminu yi ka ke noxo", fr: il y a des enfants}
    - {snk: "sere su n'ti ka ke noxo", fr: il n'y a personne dans la maison}
    - {snk: "dji su n'ti yere", fr: il n'y a pas d'eau}
  nombres:            # forme isolée / forme employée devant un nom
    - {snk: baane, compte: bane, fr: un}
    - {snk: fillo, compte: filli, fr: deux}
    - {snk: sikko, compte: sikki, fr: trois}
    - {snk: naxato, fr: quatre}
    - {snk: karago, fr: cinq}
    - {snk: tumu, fr: six}
    - {snk: nieru, fr: sept}
    - {snk: seegu, fr: huit}
    - {snk: koobu, fr: neuf}
    - {snk: tamu, compte: tami, fr: dix}
    - {snk: fana, fr: premier, note: "m'pana avec la particule"}
    - {snk: fillandi, fr: deuxième, note: "m'pillandi avec la particule"}
  demonstratifs:
    - {snk: "ke kundu", fr: ceci}
    - {snk: "ke doke", fr: cela}
    - {snk: "ke ka kundu", fr: cette maison-ci}
    - {snk: "ke ka doke", fr: cette maison-là}
  appartenance:
    - {snk: "ke kitabe ni nke ni ya xale", fr: ce livre est à moi}
    - {snk: "ke kitabe ni anke ni ya xale", fr: ce livre est à toi}
    - {snk: kitabe, fr: livre}
    - {snk: xale, fr: "marque l'appartenance", exemple: "ke kitabe ni nke ni ya xale = ce livre est à moi"}

# --- 2026-09-20, suite du texte 5 ---
texte_5_suite:
  - {snk: "ado", fr: "et", exemple: "maro ado xati = du riz et du lait"}
  - {snk: "ado na", fr: "et (entre deux ordres)", exemple: "kitabe ke wutu ado na xara = prends le livre et lis-le"}
